package com.chatgptcourses.attestations.service;

import static com.chatgptcourses.attestations.service.AttestationTypes.*;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.UUID;

/** Self-contained inert UTF-8 document. All identity/source strings are escaped as text. */
final class ParticipationHtml {
    private ParticipationHtml() { }
    static byte[] render(UUID id,String locale,Instant issued,ParticipationEvidence e){
        boolean en="en".equals(locale);String title=en?"Statement of participation":"Attestation de participation";
        var h=new StringBuilder("<!doctype html><html lang=\"").append(locale).append("\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta http-equiv=\"Content-Security-Policy\" content=\"default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'; object-src 'none'\"><title>").append(title).append("</title><style>body{font:16px/1.5 system-ui,sans-serif;max-width:70rem;margin:2rem auto;padding:0 1rem;color:#172033}h1,h2{line-height:1.2}table{border-collapse:collapse;width:100%;margin:1rem 0}th,td{border:1px solid #b6bfcb;padding:.5rem;text-align:left;overflow-wrap:anywhere}small{overflow-wrap:anywhere}section{margin:2rem 0}@media print{body{margin:0;max-width:none}thead{display:table-header-group}tr{break-inside:avoid}}</style></head><body><main><h1>").append(title).append("</h1><p><strong>").append(escape(e.participantName())).append("</strong></p><p>").append(en?"Identity declared by the participant; not verified.":"Identité déclarée par le participant, non vérifiée.").append("</p><p>").append("<span lang=\"").append(escape(e.enrolledLocale())).append("\">").append(escape(e.courseTitle())).append("</span>").append(" — ").append(en?"version ":"version ").append(e.courseVersionNumber()).append("</p><p>").append(en?"Issued on ":"Émise le ").append(issued).append("</p><p>").append(en?"This statement records participation only. It does not certify course completion, professional competence or an official qualification. No human review was performed.":"Cette attestation constate uniquement une participation. Elle ne certifie ni l’achèvement du parcours, ni une compétence professionnelle, ni un diplôme officiel. Aucune revue humaine n’a été réalisée.").append("</p>");
        h.append("<section><h2>").append(en?"Activity declarations":"Déclarations d’activité").append("</h2><p>").append(en?"Reading and completion are separate declarations by the participant.":"La lecture et l’activité déclarée terminée sont deux déclarations distinctes du participant.").append("</p><table><thead><tr><th>").append(en?"Activity":"Activité").append("</th><th>").append(en?"Reading declared":"Lecture déclarée").append("</th><th>").append(en?"Completion declared":"Déclarée terminée").append("</th></tr></thead><tbody>");
        for(var a:e.activities())h.append("<tr><td>").append(a.position()).append(". ").append("<span lang=\"").append(escape(e.enrolledLocale())).append("\">").append(escape(a.title())).append("</span>").append("<br><small>").append(a.activityVersionId()).append("</small></td><td>").append(a.readAt()==null?"—":a.readAt()).append("</td><td>").append(a.declaredCompletedAt()==null?"—":a.declaredCompletedAt()).append("</td></tr>");
        h.append("</tbody></table></section><section><h2>").append(en?"Automatically graded quizzes":"Quiz corrigés automatiquement").append("</h2><p>").append(en?"Latest recorded attempt per activity/version, independent of completion and projects.":"Dernière tentative conservée par activité/version, indépendante de l’achèvement et des projets.").append("</p><ul>");
        for(var q:e.quizzes())h.append("<li>").append(q.scorePoints()).append('/').append(q.maxPoints()).append(" ; ").append(en?"threshold ":"seuil ").append(q.passPercent()).append("% ; ").append(q.passed()?(en?"passed":"réussi"):(en?"not passed":"non réussi")).append(" ; ").append(q.submittedAt()).append(" ; ").append(escape(q.locale())).append("<br><small>").append(en?"Attempt ":"Tentative ").append(q.attemptId()).append(" ; ").append(en?"source revision ":"révision source ").append(q.sourceRevisionId()).append("</small></li>");
        h.append("</ul></section><section><h2>").append(en?"Declared self-assessments":"Autoévaluations déclarées").append("</h2><p>").append(en?"Statements made by the participant about the exact production revision shown below. No human assessor.":"Déclarations du participant portant sur la révision précise de production indiquée ci-dessous. Aucun évaluateur humain.").append("</p><ul>");
        for(var a:e.selfAssessments())h.append("<li>").append(a.scorePoints()).append('/').append(a.maxPoints()).append(" ; ").append(en?"threshold ":"seuil ").append(a.passPoints()).append(" ; ").append(a.needsRevision()?(en?"revision needed":"à reprendre"):(en?"self-assessment criteria declared met":"critères d’autoévaluation déclarés satisfaits")).append(" ; ").append(a.evaluatedAt()).append(" ; ").append(escape(a.locale())).append("<br><small>").append(en?"Production revision ":"Révision de production ").append(a.projectRevisionId()).append(" ; ").append(en?"rubric ":"grille ").append(a.rubricVersionId()).append(" ; ").append(en?"assessment ":"autoévaluation ").append(a.assessmentId()).append("</small></li>");
        h.append("</ul></section><footer><small>").append(en?"Statement reference: ":"Référence de l’attestation : ").append(id).append("<br>").append(en?"Course version: ":"Version du parcours : ").append(e.courseVersionId()).append("</small></footer></main></body></html>");
        return h.toString().getBytes(StandardCharsets.UTF_8);
    }
    private static String escape(String value){return value==null?"":value.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&#39;");}
}
